    "author": "",
    "description": "36氪获悉，东山精密发布投资者关系活动记录表公告，有投资者提问：美国相关限制法案对公司业务会产生什么影响？东山精密表示，截至目前，公司未收到客户关于相关限制法案的专门问询，下游客户需求稳定，交付有序推进，相关政策传闻暂未对公司当期经营业绩产生影响。公司持续关注海外政策动态，已提前布局多区域产能与多元化供应链方案，若未来相关政策正式落地，公司可灵活调整生产经营安排，整体影响可控。",
