    "author": "",
    "description": "36氪获悉，龙蟠科技公告，公司二级控股子公司南京锂源与浙江吉曜通行能源科技签署战略合作框架协议，约定2026年至2030年期间合计向吉曜通行销售37.86-56.78万吨磷酸铁锂正极材料，具体销售量根据订单确定，单价受原材料价格波动影响逐月确定。本次交易不构成关联交易及重大资产重组，无需提交董事会及股东会审议。公司表示，该协议有助于与下游伙伴建立长期稳定关系，增强公司在新能源电池材料领域竞争力，若顺利履行将对未来业绩产生积极影响。",
    "content": "36氪获悉，龙蟠科技公告，公司二级控股子公司南京锂源与浙江吉曜通行能源科技签署战略合作框架协议，约定2026年至2030年期间合计向吉曜通行销售37.86-56.78万吨磷酸铁锂正极材料，具体销售量根据订单确定，单价受原材料价格波动影响逐月确定。本次交易不构成关联交易及重大资产重组，无需提交董事会及股东会审议。公司表示，该协议有助于与下游伙伴建立长期稳定关系，增强公司在新能源电池材料领域竞争力，若顺利履行将对未来业绩产生积极影响。"
