    "description": "中新社北京10月8日电 (记者 谢雁冰)中国人力资源和社会保障部8日发布《新就业形态劳动者权益保障办法(征求意见稿)》，从即日起至11月8日，向社会公开征求意见。这是中国首次以规章形式，将企业实施劳动管理、不完全符合确立劳动关系情形的新就业形态劳动者纳入劳动法律制度保障。",
