    "author": "",
    "description": "中新社北京10月8日电 (记者 赵建华)中国国家税务总局8日公布的税收数据显示，刚刚结束的国庆假期，全国服务消费旺盛，相关行业日均销售收入同比增长19.5%。部分商品消费良好，家用电器、数码电子、厨卫等销售增幅较高。",
    "content": "中新社北京10月8日电 (记者 赵建华)中国国家税务总局8日公布的税收数据显示，刚刚结束的国庆假期，全国服务消费旺盛，相关行业日均销售收入同比增长19.5%。部分商品消费良好，家用电器、数码电子、厨卫等销售增幅较高。"
