    "content": "新华社长春10月8日电 题：从“出行账”看吉林文旅新景象 新华社记者金津秀、王帆 中秋国庆假期收官，吉林文旅市场的“出行账”颇具看点，照出假日市场新变化，也绘出文旅产业发展新景象。 一笔“出行账”：钟摆式出游 省成本添体验 上午8点37分，在吉林省延边朝鲜族自治州的敦化站驶出的列车上，不少乘客是前往长白山景区的游客。 “出发前就算过一笔账。”浙江游客陈欣怡说，“相比热门景区，敦化同档次民宿才三百多，高铁半小时就到，光是住宿费两人一趟能省近两千元。”白天和家人登长白山，看瀑布和天池，傍晚返程逛市区夜市、尝朝鲜族特色美…"
