    "title": "563名死囚迎“生机”？美国加州州长在田纳西州注射死刑失败后考虑大规模减刑",
    "link": "https://m.thepaper.cn/detail/34213311",
    "pub_date": "2026-10-08 19:45:08",
    "author": "澎湃新闻记者 马栎程",
    "description": "当地时间10月7日，美国加州正考虑推出一项史无前例的行政决定。加州州长加文·纽森正在评估，是否于2027年1月任期结束前，把全州现存563名死刑犯全部改判为终身监禁且不得假释。有美媒分析，近日，美国田纳西州发生一起“给死囚注射死刑药物之后，仍然存活”的案例，推动纽森加快了相关决策进程。",
    "content": "当地时间10月7日，美国加州正考虑推出一项史无前例的行政决定。加州州长加文·纽森正在评估，是否于2027年1月任期结束前，把全州现存563名死刑犯全部改判为终身监禁且不得假释。有美媒分析，近日，美国田纳西州发生一起“给死囚注射死刑药物之后，仍然存活”的案例，推动纽森加快了相关决策进程。"
