    "category": "新闻",
    "title": "综合消息丨英国驻耶路撒冷百年领馆“更名”降级",
    "link": "http://www.news.cn/20261008/48ac372d067d4b72a82ce8bcaf088264/c.html",
    "pub_date": "2026-10-08 19:45:02",
    "author": "张枫,王卓伦,陈君清,冯国芮",
    "description": "新华社北京10月8日电 综合新华社驻外记者报道：以色列外交部长萨尔和英国外交大臣米利班德8日分别表示，英国驻耶路撒冷领事馆当天停止运作。英国驻耶路撒冷领事馆大楼自8日起将改为英国驻耶路撒冷使团驻地，该使团将继续提供“重要服务”。 萨尔8日在社交媒体发文说，过去一周，以方与英国政府开展对话，旨在防止领事馆关闭导致双边关系进一步恶化，双方于7日晚达成谅解。 根据萨尔发布的帖文，包括英国驻耶路撒冷总领事在内的20名英国外交官将结束任期并离开。…",
