    "description": "新华社兰州10月8日电（记者文静）金秋国庆，甘肃迎来一年一度的绚烂秋日盛景。祁连层林、敦煌大漠、甘南山野、金塔胡杨林……凭借窗口期短、视觉冲击力强的“限时秋色”，甘肃吸引大批各地游客奔赴陇原追秋。 “一路向西，景色层层变换，边关雄风和金色林海接连登场，一次旅途收获截然不同的秋日体验。”趁着国庆假期，来自浙江温州的杨颖和朋友一行三人沿着河西环线一路西行。 在甘肃，河西走廊经典环线、祁连环线、甘南生态线等多条跨区域精品线路串联起大漠、胡杨、…",
