    "content": "中新网海口10月8日电 (记者 王子谦)2026年国庆假期，是海南自贸港封关运作后的首个国庆长假。记者8日从海南省交通运输厅获悉，10月1日至7日，海南全省进出岛旅客164.95万人次，较2024年增长8.47%、较2025年增长11.76%。"
