    "description": "新华社苏瓦10月8日电（记者郭鑫惠 白涌泉）维拉港消息：南太平洋岛国瓦努阿图附近海域8日发生6.3级地震。目前暂无人员伤亡或财产损失报告。 据美国地质调查局地震信息网消息，地震发生在当地时间8日20时（北京时间17时），震中位于瓦努阿图诺尔苏普东北102公里处，震源深度10公里。 太平洋海啸预警中心没有针对这次地震发布海啸预警。中国驻瓦努阿图大使馆工作人员告诉记者，瓦努阿图首都维拉港没有震感。 瓦努阿图位于环太平洋火山地震带，因地壳板块…",
    "content": "新华社苏瓦10月8日电（记者郭鑫惠 白涌泉）维拉港消息：南太平洋岛国瓦努阿图附近海域8日发生6.3级地震。目前暂无人员伤亡或财产损失报告。 据美国地质调查局地震信息网消息，地震发生在当地时间8日20时（北京时间17时），震中位于瓦努阿图诺尔苏普东北102公里处，震源深度10公里。 太平洋海啸预警中心没有针对这次地震发布海啸预警。中国驻瓦努阿图大使馆工作人员告诉记者，瓦努阿图首都维拉港没有震感。 瓦努阿图位于环太平洋火山地震带，因地壳板块相互碰撞而频发地震。"
