    "description": "大家好，我是 TrueSOTA 的站方运营，站点地址：TrueSOTA 看到有评论说：“中转站太多了，想找一个能生图得太难找了。”借这个反馈，和大家说一下我们正在排期的批量生图功能。 目前的设计是一次提交多条提示词，任务完成后统一下载图片结果，并通过批量任务列表查看、筛选任务。对于要准备一组素材，或想试多条提示词效果的用户，我们希望能减少反复提交、逐张下载和查找结果的麻烦。 批量生图已有排期，计划不久后开放使用，目前还没有正式上线。配图…",
    "content": "大家好，我是 TrueSOTA 的站方运营，站点地址： TrueSOTA 看到有评论说：“中转站太多了，想找一个能生图得太难找了。”借这个反馈，和大家说一下我们正在排期的批量生图功能。 目前的设计是一次提交多条提示词，任务完成后统一下载图片结果，并通过批量任务列表查看、筛选任务。对于要准备一组素材，或想试多条提示词效果的用户，我们希望能减少反复提交、逐张下载和查找结果的麻烦。 批量生图已有排期，计划不久后开放使用，目前还没有正式上线。配图先展示界面设计，不代表全部功能都已完成；具体开放时间和支持范围，以后续公告为准…"
