    "description": "新华社北京10月8日电 题：供应链金融创新发展，助力缓解中小企业资金难题 新华社记者吴雨 中小企业回款难、产业链上下游中小企业资金压力问题备受关注。记者调研了解到，当前，治理中小企业回款难正持续推进，特别是供应链金融加快创新发展，推动金融服务从“看抵押”转向“看链条”，正成为缓解中小企业资金难题的有力抓手。 在福建南安，九牧集团的黑灯工厂正加紧赶制“双十一”卫浴产品，上游企业稳定供应原材料，下游经销商订单源源不断。 “产业链平稳运转的背…",
    "content": "新华社北京10月8日电 题：供应链金融创新发展，助力缓解中小企业资金难题 新华社记者吴雨 中小企业回款难、产业链上下游中小企业资金压力问题备受关注。记者调研了解到，当前，治理中小企业回款难正持续推进，特别是供应链金融加快创新发展，推动金融服务从“看抵押”转向“看链条”，正成为缓解中小企业资金难题的有力抓手。 在福建南安，九牧集团的黑灯工厂正加紧赶制“双十一”卫浴产品，上游企业稳定供应原材料，下游经销商订单源源不断。 “产业链平稳运转的背后，离不开建行对上下游企业累计超37亿元的融资支持。”九牧集团产业金融部总经理李…"
