    "content": "网红“面筋哥”程书林去世一年半年后，近日又因为AI内容重新出现在网友视野中。相关贴吧讨论和B站视频显示，其家人及相关账号开始尝试利用AI技术还原面筋哥的形象与声音，并制作成短剧等内容。由于程书林本人已经去世，这种“让面筋哥继续出镜”的做法迅速引发网友争议。 程书林曾凭借《烤面筋》走红网络，后来又因为鬼畜二创成为B站早期极具代表性的网络人物。2025年3月29日，他因病抢救无效在郑州去世，终年52岁。去世后，其家人仍持续运营相关社交账号，并陆续发布纪念内容。 此次AI内容出现后，部分网友认为，这种方式能够帮助粉丝继续…"
