    "content": "快科技10月8日消息，据Electrek报道，现代汽车已悄然取消IONIQ 3在澳大利亚的上市计划。 现代发言人向澳大利亚媒体Drive直言，将这款车进口到澳洲太困难且成本过高，在当前竞争环境下“账算不过来”。 据了解，IONIQ 3原计划2027年初在澳大利亚上市，预售起价约4万澳元， 现代已从澳洲官网上悄然移除了该车的落地页面。 现代发言人表示：“进口成本很高，而这辆车将进入一个对价格极其敏感的细分市场。考虑到竞争环境，这些数字对我们来说不成立。” 而让现代打退堂鼓的核心原因，是中国电动车在澳洲市场的全面碾压。…"
