    "content": "新华社武汉10月8日电（记者熊翔鹤）拾级走上武汉知音文化旅游区龟山公园的林间步道，桂花开得正盛。一路上，在鲁山驿道遇见将士行迎宾礼，在桂月亭听说书人讲《汉津口》，在拂云亭看湖北小曲与湖北大鼓同台演绎《子期听琴》，在知音殿体验《三国群芳宴》沉浸式餐饮秀…… “山还是那座山，能看能玩的内容却多了不少。”武汉青年谢宇哲在武汉工作，每逢有外地朋友到访，他总会带客人爬上龟山，远眺江水、大桥和黄鹤楼。“以前上山就是看看风景、吹吹江风，今年国庆一路走一路有演出，各种戏曲、歌舞、情景剧应接不暇。原本预计一个小时的行程，我们在这待了…"
