    "title": "深圳铁路国庆假期到发旅客超600万人次",
    "link": "https://www.chinanews.com.cn/gn/2026/10-08/10709265.shtml",
    "pub_date": "2026-10-08 18:43:17",
    "author": "",
    "description": "中新网深圳10月8日电 (索有为 马鑫宇 岳千琳)2026年国庆假期(10月1日至10月7日)，深圳铁路迎来探亲、旅游、学生等多重客流叠加的出行高峰。据深圳铁路部门8日发布的统计数据，假期期间深圳铁路到发旅客633.68万人次，其中发送旅客310.96万人次、到达旅客322.72万人次，同比去年国庆假期增幅达14.08%。",
    "content": "中新网深圳10月8日电 (索有为 马鑫宇 岳千琳)2026年国庆假期(10月1日至10月7日)，深圳铁路迎来探亲、旅游、学生等多重客流叠加的出行高峰。据深圳铁路部门8日发布的统计数据，假期期间深圳铁路到发旅客633.68万人次，其中发送旅客310.96万人次、到达旅客322.72万人次，同比去年国庆假期增幅达14.08%。"
