    "author": "澎湃新闻记者 喻琰",
    "description": "一则在社交平台发布的信息，将具身智能行业的基础设施——数据采集中心（简称数采中心）推上了风口浪尖。 日前，一家刚刚上市的具身智能企业创始人在朋友圈发声质疑，有同行企业利用数采中心及与地方政府、投资人、供应商之间的关联交易，制造了“虚假的、不可持续的收入”，目的是推动上市。 一时间，关于数采中心的角色定位、数据质量、关联交易的讨论，持续展开。有人认为，这是产业发展早期必需的产业协同；也有人提出，数采中心所生产的庞大数据，有多少实现了真正流…",
    "content": "一则在社交平台发布的信息，将具身智能行业的基础设施——数据采集中心（简称数采中心）推上了风口浪尖。 日前，一家刚刚上市的具身智能企业创始人在朋友圈发声质疑，有同行企业利用数采中心及与地方政府、投资人、供应商之间的关联交易，制造了“虚假的、不可持续的收入”，目的是推动上市。 一时间，关于数采中心的角色定位、数据质量、关联交易的讨论，持续展开。有人认为，这是产业发展早期必需的产业协同；也有人提出，数采中心所生产的庞大数据，有多少实现了真正流通和应用？数采中心和具身智能企业之间的关系，以及多方“共建”之下，数采中心的效率…"
