    "title": "想问下特定的桌面环境跟特定的窗口管理器是相互榜单的关系吗",
    "link": "https://forum.archlinuxcn.org/t/topic/17367#post_3",
    "pub_date": "2026-10-08 18:28:31",
    "author": "",
    "description": "因为 plasmashell 使用了大量 kwin 独有的接口，有些功能离了 kwin 不太正常。 比较火的几个平铺式窗管，都可以换桌面 shell ，比如我现在是 niri 搭配 noctalia ，感觉功能性和自定义程度已经比较接近 plasmashell 了",
    "content": "因为 plasmashell 使用了大量 kwin 独有的接口，有些功能离了 kwin 不太正常。 比较火的几个平铺式窗管，都可以换桌面 shell ，比如我现在是 niri 搭配 noctalia ，感觉功能性和自定义程度已经比较接近 plasmashell 了"
