    "content": "新华社北京10月8日电（记者王鹏）记者8日从教育部获悉，教育部、财政部近日部署实施2026年银龄讲学计划，计划招募义务教育阶段银龄讲学教师6000名。 据介绍，2026年银龄讲学计划主要面向脱贫县，欠发达的民族县、革命老区县、边境县以及新疆生产建设兵团团场等实施，重点向国家乡村振兴重点帮扶县倾斜。也鼓励各省份结合实际，自主选拔优秀退休教师到其他教育发展薄弱的县乡地区开展讲学，根据需要将普通高中纳入自主实施范围。 根据要求，申请银龄讲学计划的退休教师以校长、教研员、特级教师、骨干教师为主。要求政治可靠、师德高尚、教育…"
