    "description": "多年前，他常常去香港，在某个网站上挂个招嫖广告，就能接迎来很多生意，一去就是一个星期，1 个星期能赚个几万港币，因为他经常在朋友圈那里晒，还晒买了什么什么。几乎每隔一个星期就去那边，甚至有时隔几天就去。起码持续了两年这样，应该是赚了多挺多钱的了，买了房买了车，名牌包包，手机、ipad 经常换，有些是客户送的。 也许你好奇他的长相，长得比较像个泰国人，不算很帅，非肌肉男，但算得上壮，黑溜溜的，典型的成都基佬形象。某一年，他说他要结婚了，是…",
    "content": "多年前，他常常去香港，在某个网站上挂个招嫖广告，就能接迎来很多生意，一去就是一个星期，1 个星期能赚个几万港币，因为他经常在朋友圈那里晒，还晒买了什么什么。几乎每隔一个星期就去那边，甚至有时隔几天就去。起码持续了两年这样，应该是赚了多挺多钱的了，买了房买了车，名牌包包，手机、ipad 经常换，有些是客户送的。 也许你好奇他的长相，长得比较像个泰国人，不算很帅，非肌肉男，但算得上壮，黑溜溜的，典型的成都基佬形象。某一年，他说他要结婚了，是去庙里拜神，一女的看上了他，主动加的联系方式，甚至提亲都是女的主动上门，后来真的…"
